// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    function setUp() public { c = new Private_Bank(address(new Log())); }

    function testFuzz_property(uint256 value, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(value <= 1 ether); // deposit not strictly greater than MinDeposit
        vm.deal(actor, value);
        uint256 before = c.balances(actor);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: value}(abi.encodeWithSignature("Deposit()"));
        assertTrue(ok && c.balances(actor) == before);
    }
}
